#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long long a = strtoll(argv[1], &end1, 10);
    long long b = strtoll(argv[2], &end2, 10);
    // ensure full conversion
    if (end1 != argv[1] + strlen(argv[1]) || end2 != argv[2] + strlen(argv[2])) {
        puts("BAD_INPUT");
        return 0;
    }
    // range check on numerator (absolute value)
    if (a < -100000LL || a > 100000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // make denominator positive, adjust sign of numerator accordingly
    if (b < 0) {
        a = -a;
        b = -b;
    }
    // special case: denominator zero -> just output the integer
    if (b == 0) {
        printf("[%lld]", a);
        return 0;
    }
    long long terms[200];
    int n = 0;
    long long num = a, den = b;
    while (den != 0 && n < 200) {
        long long q = num / den;
        long long r = num % den;
        // adjust for floor division when remainder is negative
        if (r < 0) {
            if (den > 0) {
                q -= 1;
                r += den;
            } else {
                q += 1;
                r -= den;
            }
        }
        terms[n++] = q;
        num = den;
        den = r;
    }
    if (den != 0) { // more than 199 terms
        puts("ERROR");
        return 0;
    }
    // output in the form [a0; a1, a2, ...]
    putchar('[');
    for (int i = 0; i < n; ++i) {
        if (i == 0) {
            printf("%lld", terms[i]);
        } else if (i == 1) {
            printf("; %lld", terms[i]);
        } else {
            printf(", %lld", terms[i]);
        }
    }
    putchar(']');
    return 0;
}
